  ?s rdfs:label "Perimeter_mid_ZN_4" .
  ?s brick:hasType ?class .
  OPTIONAL { ?s ?r ?o . }
  LIMIT 20
}

PREFIX brick: <http://brickschema.org/schema/1.2/Brick#>
PREFIX ref: <http://w3id.org/brick/ref#>
SELECT ?p ?class ?tsid
WHERE {
  ?brick_zone a brick:Zone .
  FILTER (str(?brick_zone) = "http://buildgraph.org/BG_large_office_2004_0000#Zone_F3_Z05")
  {
    ?p brick:hasProperty ?brick_zone .
  }
  ?p ?class ?o .
  OPTIONAL { ?p ref:hasTimeseriesId ?tsid . }
}

